$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'Автоматическая настройка создаёт вебхук только для URL этого сайта или добавляет в него недостающие события, сохраняя остальные. Она сохраняет Webhook ID, используемый для проверки подписей. Она никогда не удаляет вебхуки, не затрагивает другие URL и не меняет разрешения приложения.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'Для автоматической настройки требуется разрешение Webhook Endpoints: Write. Она создаёт вебхук и надёжно сохраняет его новый секрет подписи либо включает существующую конечную точку и добавляет недостающие события. Существующие события сохраняются, конечные точки не заменяются, а разрешения API-ключа не меняются.';
