$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Финальная проверка: совершите покупку в песочнице, убедитесь в доставке с кодом HTTP 200 в Stripe, затем проверьте кошелёк или аренду, доступ по подписке и воспроизведение видео. Также проверьте отклонённую карту и 3D Secure. Никогда не повторяйте оплаченный платёж только потому, что доступ ещё ожидает предоставления.';
$t['Final test: complete a sandbox purchase with a Personal sandbox buyer, confirm an HTTP 200 webhook delivery in developer.paypal.com, then check the wallet, rental, subscription and video playback. Never retry a paid purchase just because access is still pending.'] = 'Финальная проверка: совершите покупку в песочнице с помощью тестового покупателя Personal, убедитесь в доставке вебхука с кодом HTTP 200 на developer.paypal.com, затем проверьте кошелёк, аренду, подписку и воспроизведение видео. Никогда не повторяйте оплаченную покупку только потому, что доступ ещё ожидает предоставления.';
