$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Коммит определяет ревизию Git, извлечённую на этом сервере; локальные изменения файлов не учитываются. Тег Git отображается, если он указывает непосредственно на этот коммит.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Сервис Companion Chat сейчас недоступен. Попросите администратора сайта проверить подключение плагина AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Не удалось продлить подключение. Подключите аккаунт заново.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Срок действия подключения истёк, и его не удалось продлить. Подключите аккаунт заново.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Соединение с пунктом назначения прервалось во время трансляции. Это может быть временная проблема с сетью; FFMPEG попытается переподключиться.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Соединение с YouTube было прервано. Загрузка приостановлена, её можно возобновить.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Соединение было прервано. Проверьте аккаунт, прежде чем повторить оформление подписки.';
$t['The connection was renewed.'] = 'Подключение продлено.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Окно подключения было закрыто до завершения авторизации. Аккаунт не подключён.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Конвертированные файлы сохранены. Обратитесь к администратору сайта, чтобы повторить передачу; загружать видео заново не нужно.';
$t['The converted video could not be sent back to this site.'] = 'Не удалось отправить сконвертированное видео обратно на этот сайт.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Клиенты выбранной карточки. Ищите, сортируйте, копируйте e-mail или экспортируйте всё в таблицу.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Дневная квота загрузок на YouTube для этого сайта исчерпана. Загрузка снова станет доступна после полуночи по тихоокеанскому времени. Пожалуйста, повторите попытку позже.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Версия базы данных меняется только при применении миграции базы данных. Она не обязана совпадать с тегом релиза или коммитом.';
$t['The default'] = 'По умолчанию';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Целевой RTMP-сервер отклонил подключение. Проверьте URL трансляции и убедитесь, что сервер доступен.';
$t['The destination server requires authentication. Check the stream key.'] = 'Целевой сервер требует аутентификации. Проверьте ключ трансляции.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Целевой сервер вернул ошибку 403. Возможно, ключ трансляции недействителен или истёк.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Целевое видео удалено, или этот аккаунт не может его редактировать. Проверьте видео и доступ аккаунта на сайте.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'Загрузка контролируется системой, ничего не нужно проверят';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Разрешение на скачивание действует для всего сайта, поэтому для видео проверять нечего';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'Разрешение на загрузку распространяется на весь сайт, поэтому проверять видео не нужно';
$t['The email is invalid'] = 'Адрес электронной почты недействителен';
$t['The encoder could not download the original file.'] = 'Энкодеру не удалось скачать исходный файл.';
$t['The encoder could not find this video on the site.'] = 'Энкодер не нашёл это видео на сайте.';
