$t['The encoder is running out of disk space'] = 'У энкодера заканчивается место на диске';
$t['The encoder reported an unexpected error.'] = 'Энкодер сообщил о непредвиденной ошибке.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Процесс кодирования неожиданно остановился, и автоматические повторные попытки тоже не удались.';
$t['The encoding queue is stalled'] = 'Очередь кодирования остановилась';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Не удалось завершить покупку события. Средства с вашего кошелька не списаны. Проверьте баланс перед повторной попыткой.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Не удалось сконвертировать файл. Возможно, он повреждён или имеет формат, который энкодер не поддерживает.';
$t['The file must be an .vtt file!'] = 'Файл должен быть в формате .vtt!';
$t['The file must be an .vtt or .srt file!'] = 'Файл должен быть в формате .vtt или .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Итоговая сумма рассчитывается по длительности, измеренной при обработке. Требуется подключённый кошелёк Marketplace.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Следующий фильм содержит материалы, не предназначенные для детей до 17 лет включительно.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Следующий фильм содержит материалы, которые могут быть неприемлемы для детей до 17 лет включительно.';
$t['The form to signup will not exists'] = 'Форма для регистрации будет отключена';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Подарочный код отменён. Если это неожиданно, обратитесь в нашу службу поддержки.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Подарочный код сейчас неактивен. Попробуйте позже или обратитесь в поддержку.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Приведённые выше сведения соответствуют нашим официальным записям и подтверждают подлинность этого сертификата.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Входной поток содержит недопустимые данные. Возможно, исходный HLS ещё не готов или трансляция была прервана.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Установленный пакет PHP содержит оба исправления, но этот веб-процесс всё ещё использует копию, загруженную до обновления. Перезапустите Apache или PHP-FPM.';
$t['Their last plans add up to %s'] = 'Их последние планы в сумме составляют %s';
$t['The list was limited to the first %s results.'] = 'Список ограничен первыми %s результатами.';
$t['The live service could not complete the request. Please try again.'] = 'Сервису трансляций не удалось выполнить запрос. Пожалуйста, попробуйте ещё раз.';
$t['The live that was still being sent to this destination was stopped.'] = 'Трансляция, которая ещё передавалась в это место назначения, остановлена.';
$t['Theme for Style:'] = 'Тема для стиля:';
$t['Themes'] = 'Тема';
$t['The number of lines in both columns must be the same'] = 'Количество строк в обоих столбцах должно совпадать';
$t['The original file for this video does not exists anymore'] = 'Оригинальный файл для этого видео больше не существует';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'Плагин разрешений не установлен. Пожалуйста, установите его, если вы хотите настроить разрешения.';
$t['The plugin is disabled'] = 'Плагин отключен';
$t['The program is empty'] = 'Программа пуста';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Не удалось завершить покупку. Средства с вашего кошелька не списаны. Проверьте баланс перед повторной попыткой.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'У этого подарочного кода неизвестный статус. Обратитесь в поддержку за помощью.';
$t['There, you can set'] = 'Там можно установить';
$t['There are no notifications'] = 'Уведомлений нет';
$t['There are no upcoming events for this channel'] = 'У этого канала нет предстоящих событий';
$t['There are various kinds of media you can integrate here. They are working different'] = 'Здесь можно интегрировать различные виды медиа. Они работают по-разному';
$t['The recover pass does not match!'] = 'Восстановленный доступ не совпадает!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'Обычная форма для входа будет отключена, если вы установите флажок, в ней будет только опция соц. входа или LDAP';
$t['There is missing data to recover your password'] = 'Отсутствуют данные для восстановления пароля';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Плана Pay Per View пока нет. Создайте его в плагине Pay-Per-View на вкладке «Планы PPV».';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Пока нет плана, который может содержать видео. Создайте его на вкладке «Планы PPV» и вернитесь сюда.';
$t['There is no streaming now'] = 'Сейчас нет трансляции';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Номер релиза и версия базы данных AVideo независимы. Статус обновления кода определяется по истории коммитов.';
$t['The request to the social network failed. Please try again later.'] = 'Запрос к социальной сети не выполнен. Пожалуйста, повторите попытку позже.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Сервер ретрансляции не может связаться с местом назначения. Проверьте сетевое подключение.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Одно и то же оповещение повторяется не чаще чем раз в %s, пока проблема сохраняется.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Одно и то же оповещение повторяется не чаще чем раз в несколько часов, пока проблема сохраняется.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Выбранная камера или микрофон недоступны. Выберите другое устройство.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Выбранная позиция подсвечивается на реальной странице. Мобильный предпросмотр меняет только позиции рекламы; остальная часть страницы использует устройство вашего браузера.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Выбранная позиция выделяется на реальной странице вашего сайта и меняется вслед за позицией, выбранной ниже. Мобильный предпросмотр меняет только рекламные позиции; остальная часть страницы отображается для устройства вашего браузера.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Сайт временно недоступен из-за проблемы с базой данных. Мы работаем над её скорейшим устранением.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Сайт временно недоступен, так как диск сервера заполнен. Мы работаем над этой проблемой и скоро вернёмся.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'На сайте ведутся технические работы, так как диск сервера почти заполнен. Мы решаем проблему и скоро вернёмся.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Сайт отказал в доступе. Обновите доступ аккаунта энкодера и проверьте его права на загрузку.';
$t['The site will display only a login form to un authenticated users'] = 'Сайт будет отображать только форму входа для не авторизованных пользователей';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Исходный поток завершился. Если трансляция была остановлена намеренно, это нормально.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Разделение включено: посетители с компьютеров сейчас не видят этот баннер, они видят левую и правую половины.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'В потоке есть разрывы временных меток. Это может вызывать буферизацию или проблемы воспроизведения на целевой платформе.';
$t['The subtitle has not been copied to the player yet.'] = 'Субтитры ещё не скопированы в плеер.';
$t['The subtitle is already on the player.'] = 'Субтитры уже есть в плеере.';
$t['The subtitle was copied to the player.'] = 'Субтитры скопированы в плеер.';
$t['The subtitle will be available when processing finishes.'] = 'Субтитры станут доступны после завершения обработки.';
$t['The upload could not be started. Please try again.'] = 'Не удалось начать загрузку. Пожалуйста, попробуйте ещё раз.';
$t['The upload did not start. Click Resume to try again.'] = 'Загрузка не началась. Нажмите «Продолжить», чтобы повторить попытку.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'Загрузка на YouTube началась. Ниже можно следить за её ходом, она продолжится, даже если вы закроете это окно.';
$t['The upload was canceled.'] = 'Загрузка отменена.';
$t['The upload was interrupted. Click Resume to continue from where it stopped.'] = 'Загрузка прервана. Нажмите «Продолжить», чтобы продолжить с места остановки.';
$t['The upload was resumed.'] = 'Загрузка возобновлена.';
$t['the user is inactive'] = 'пользователь неактивен';
$t['The username must be an email'] = 'Имя пользователя должно быть электронной почтой';
$t['The user will be able to edit their name and CPF.'] = 'Пользователь сможет изменить своё имя и CPF.';
$t['The video could not be published. Please try again later.'] = 'Не удалось опубликовать видео. Пожалуйста, повторите попытку позже.';
$t['The video file could not be found on this server, so it cannot be sent to YouTube.'] = 'Файл видео не найден на этом сервере, поэтому его нельзя отправить на YouTube.';
