$t['They are likely to leave at renewal time. Invite them back with a suggested course or a live class.'] = 'Скорее всего, они уйдут при продлении. Пригласите их вернуться, предложив курс или живое занятие.';
$t['They have paid %s in total'] = 'Всего они заплатили %s';
$t['The YouTube authorization could not be renewed because the authorization service did not answer. Please try again in a few minutes.'] = 'Не удалось обновить авторизацию YouTube, так как служба авторизации не ответила. Пожалуйста, повторите попытку через несколько минут.';
$t['The YouTube categories could not be loaded, YouTube will choose one.'] = 'Не удалось загрузить категории YouTube, YouTube выберет категорию сам.';
$t['The YouTube integration is not configured correctly. Please contact the site administrator.'] = 'Интеграция с YouTube настроена неправильно. Обратитесь к администратору сайта.';
