$t['Third Party Ads'] = 'Сторонняя реклама';
$t['This account has been disabled. Contact support for details.'] = 'Этот аккаунт отключён. Обратитесь в поддержку за подробностями.';
$t['This account is disabled because the connected marketplace wallet balance ran out. Add credits to your marketplace wallet to reactivate automatically - content is at risk of deletion after 24 hours.'] = 'Этот аккаунт отключён, так как баланс подключённого кошелька маркетплейса исчерпан. Пополните кошелёк маркетплейса, чтобы аккаунт автоматически активировался снова, — через 24 часа контент может быть удалён.';
$t['This action can not be recovered!'] = 'Это действие невозможно отменить!';
$t['This action cannot be undone. The user will need to confirm their identity again.'] = 'Это действие нельзя отменить. Пользователю придётся снова подтвердить свою личность.';
$t['This ad goes on the LEFT half of the banner.'] = 'Эта реклама размещается в ЛЕВОЙ половине баннера.';
$t['This ad goes on the RIGHT half of the banner.'] = 'Эта реклама размещается в ПРАВОЙ половине баннера.';
