$t['This also reset the Chat and views counter'] = 'Это также сбросит чат и счётчик просмотров';
$t['This Bitcoin invoice was marked invalid. If you sent a payment, contact support with the reference on this page.'] = 'Этот Bitcoin-счёт помечен как недействительный. Если вы отправили платёж, обратитесь в поддержку, указав номер с этой страницы.';
$t['This button is always a click worth'] = 'На эту кнопку всегда стоит нажать';
