$t['This creates a download-button under your video, suggest you title.mp4 as download-name.'] = 'Это создаст кнопку загрузки под вашим видео, предложив вам title.mp4 в качестве имени загрузки.';
$t['This destination is still sending a live and it could not be stopped, so it was not deleted. Stop it in Active Lives and try again.'] = 'Это место назначения всё ещё передаёт трансляцию, и её не удалось остановить, поэтому оно не было удалено. Остановите её в разделе «Активные трансляции» и повторите попытку.';
$t['This e-mail will be used for this web site notifications'] = 'Этот адрес электронной почты будет использоваться для уведомлений этого веб-сайта.';
$t['This event is not available for purchase.'] = 'Это событие недоступно для покупки.';
$t['This export includes only data stored in wallet and wallet_log tables, plus user and email from users table.'] = 'Этот экспорт включает только данные из таблиц wallet и wallet_log, а также user и email из таблицы users.';
$t['This file has lines that could not be read; fix it by hand'] = 'В этом файле есть строки, которые не удалось прочитать; исправьте их вручную';
$t['This gift code has already been redeemed. If you believe this is an error, please reach out to our support.'] = 'Этот подарочный код уже использован. Если вы считаете, что это ошибка, обратитесь в нашу поддержку.';
$t['This gift or its plan is unavailable'] = 'Этот подарок или его план недоступен';
$t['This gift plan is unavailable'] = 'Этот подарочный план недоступен';
$t['This Google account does not have a YouTube channel yet. Create a channel on YouTube, then try again.'] = 'У этого аккаунта Google ещё нет канала YouTube. Создайте канал на YouTube и повторите попытку.';
$t['this help'] = 'это поможет';
$t['This help us to track and detect errors'] = 'Это помогает нам отслеживать и выявлять ошибки';
$t['This help us to track and dettect errors'] = 'Это помогает нам отслеживать и обнаруживать ошибки';
$t['This image will appear in your livestream'] = 'Это изображение будет показано в вашей трансляции';
$t['This information will be permanently recorded on your certificates and cannot be changed later without administrator approval.'] = 'Эти данные будут навсегда указаны в ваших сертификатах, и изменить их позже можно будет только с одобрения администратора.';
$t['This installation or wallet is already linked to another organization. Contact the platform administrator to review the connection.'] = 'Эта установка или кошелёк уже привязаны к другой организации. Обратитесь к администратору платформы, чтобы проверить привязку.';
$t['This is a level below the (Videos Admin), this type of user can change the video publicity (Active, Inactive, Unlisted)'] = 'Это уровень ниже (Администратор видео), этот тип пользователей может изменять публикацию видео (активный, Неактивный, Не внесенный в список)';
$t['This is an experimental resource'] = 'Это экспериментальный ресурс';
$t['This is a one-time wallet top-up. It does not start a subscription.'] = 'Это разовое пополнение кошелька. Оно не оформляет подписку.';
$t['This is not a valid email'] = 'Это неверный адрес электронной почты.';
$t['This is not a valid URL'] = 'Это неверный URL';
$t['This is taking longer than usual. Use Check payment status to check again; no new charge will be made.'] = 'Это занимает больше времени, чем обычно. Нажмите «Проверить статус платежа», чтобы проверить снова; повторного списания не будет.';
$t['This is the fixed price for all certificates'] = 'Это фиксированная цена для всех сертификатов';
$t['This is useful if you want to use our LDAP plugin or maybe only allow authentication from Social Networks'] = 'Это полезно, если вы хотите использовать наш плагин LDAP или разрешить аутентификацию только из социальных сетей.';
$t['This is where you can create groups and associate them with your videos and users. This will make your videos private. Only users who are in the same group as the videos can view them'] = 'Здесь вы можете создавать группы и связывать их с вашими видео и пользователями. Это сделает ваши видео приватными. Только пользователи, которые находятся в той же группе, что и видео, могут просматривать их';
$t['This Live Requires a Password'] = 'Для этой трансляции требуется пароль';
$t['This live will be private and restricted to selected user groups. Do you want to proceed?'] = 'Эта трансляция будет приватной и доступной только выбранным группам пользователей. Продолжить?';
$t['This Meet Requires a Password'] = 'Для этой встречи требуется пароль';
$t['This Month'] = 'Этот месяц';
$t['This observation covers only the process serving this request, not every worker, node, container or separate Encoder. Check each environment.'] = 'Эта проверка охватывает только процесс, обрабатывающий данный запрос, а не все воркеры, узлы, контейнеры или отдельный Encoder. Проверьте каждое окружение.';
$t['This option will not make your videos private, this option is for other users not to be able to include their videos in this category. to make your videos private use the user groups feature'] = 'Эта опция не сделает ваши видео приватными, эта опция предназначена для того, чтобы другие пользователи не могли включать свои видео в эту категорию. чтобы сделать ваши видео приватными, используйте функцию групп пользователей';
